JS=r'''#!/usr/bin/env node
'use strict';
const cp = require('node:child_process');
const path = require('node:path');
const fs = require('node:fs');
const root = path.join(__dirname, 'runtime', process.platform + '-' + process.arch);
const launcher = path.join(root, 'launch.py');
if (!fs.existsSync(launcher)) {
  console.error('GitSit beta: this operating system/architecture is not included in this package.');
  process.exit(1);
}
let py;
for (const cmd of ['python3', 'python']) {
  const p = cp.spawnSync(cmd, ['-c', 'import sys; print(sys.executable); sys.exit(0 if sys.version_info >= (3,11) else 1)'], {encoding:'utf8', timeout:5000, windowsHide:true});
  if (p.status === 0 && p.stdout.trim()) { py = p.stdout.trim(); break; }
}
if (!py) { console.error('GitSit requires Python 3.11+ on PATH. On macOS use Homebrew or python.org.'); process.exit(1); }
const child = cp.spawn(py, [launcher, ...process.argv.slice(2)], {stdio:'inherit', env:{...process.env,PYTHONUTF8:'1'}});
// The attached terminal delivers Ctrl+C to the foreground process group; do not exit the wrapper prematurely.
process.on('SIGINT', () => {});
child.on('error', () => { console.error('GitSit could not start. Reinstall the package.'); process.exitCode=1; });
child.on('exit', (code, signal) => { process.exitCode=code ?? (signal==='SIGINT'?130:1); });
'''

def run(args,cwd=None,env=None,timeout=900):
    print('>', ' '.join(map(str,args)),flush=True)
    subprocess.run([str(a) for a in args],cwd=cwd,env=env,check=True,timeout=timeout)
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def write(p,s):p.write_text(s,encoding='utf-8')
def clean_env():
    return {k:v for k,v in os.environ.items() if not k.startswith(('GH_','GITHUB_TOKEN','GIT_CONFIG','GIT_DIR','GIT_WORK_TREE','GIT_INDEX_FILE','GITLEAKS_','PYTHONPATH','PYTHONHOME'))}
def unpack(dest):
    if dest.exists():raise RuntimeError('Destination exists; choose another --output. Nothing overwritten: '+str(dest))
    dest.mkdir(parents=True)
    with zipfile.ZipFile(io.BytesIO(base64.b85decode(PAYLOAD))) as z:
        for n in z.namelist():
            p=Path(n)
            if p.is_absolute() or '..' in p.parts:raise RuntimeError('Invalid embedded path')
        z.extractall(dest)
    print('GitSit source prepared:',dest)
def checks(root):
    pkg=root/'source/gitsit_studio'; env=dict(clean_env(),PYTHONUTF8='1')
    run([sys.executable,'test_native.py'],cwd=pkg,env=env,timeout=180)
    run([sys.executable,root/'tests/test_onboarding.py'],env=env,timeout=180)
    run([sys.executable,'launch.py','--version'],cwd=pkg,env=env)
    run([sys.executable,'launch.py','--graph-check'],cwd=pkg,env=env)
def host():
    machine=platform.machine().lower(); arch={'aarch64':'arm64','arm64':'arm64','x86_64':'x64','amd64':'x64'}.get(machine)
    if sys.platform not in ('darwin','linux') or arch is None:raise RuntimeError('Windows and other architectures are blocked pending a native engine port and tests. Do not publish a Windows binary from this source.')
    return sys.platform,arch

def npm_pack(runtimes,out,license_text,repo):
    with tempfile.TemporaryDirectory(prefix='gitsit-npm-') as t:
        p=Path(t); (p/'runtime').mkdir()
        for key,src in runtimes.items():shutil.copytree(src,p/'runtime'/key)
        meta={'name':'gitsit','version':NPM_VERSION,'description':'GitSit Studio — You code. We handle Git.','bin':{'gitsit':'cli.js'},'files':['cli.js','runtime','README.md','LICENSE'],'engines':{'node':'>=18'},'repository':{'type':'git','url':'https://github.com/'+repo+'.git'},'license':'MIT' if license_text==MIT else 'SEE LICENSE IN LICENSE','keywords':['git','github','cli','tui','version-control']}
        if len(runtimes)==1:
            osname,arch=next(iter(runtimes)).split('-');meta.update(os=[osname],cpu=[arch])
        write(p/'package.json',json.dumps(meta,indent=2)+'\n');write(p/'cli.js',JS);(p/'cli.js').chmod(0o755)
        write(p/'LICENSE',license_text);write(p/'README.md','# GitSit Studio\nYou code. We handle Git.\n\nBeta. Requires Python 3.11+, Git, GitHub CLI and Gitleaks for uploads. Included targets: '+', '.join(runtimes)+'. No automatic install scripts.\n')
        run(['npm','pack','--ignore-scripts','--pack-destination',out],cwd=p,timeout=120)
    return out/f'gitsit-{NPM_VERSION}.tgz'

def formula(manifests,repo):
    macs=[m for m in manifests if m['os']=='darwin']
    if not macs:return None
    if len(macs)==1:
        m=macs[0];sel=f'  depends_on arch: {":arm64" if m["arch"]=="arm64" else ":x86_64"}\n  url "https://github.com/{repo}/releases/download/{TAG}/{m["archive"]}"\n  sha256 "{m["sha256"]}"\n';minimum=m['minimum_macos']
    else:
        sel='';minimum=max((m['minimum_macos'] for m in macs),key=lambda x:tuple(map(int,x.split('.'))))
        for m in macs:
            sel+=f'  on_{"arm" if m["arch"]=="arm64" else "intel"} do\n    url "https://github.com/{repo}/releases/download/{TAG}/{m["archive"]}"\n    sha256 "{m["sha256"]}"\n  end\n'
    return f'''class Gitsit < Formula
  desc "Intent-driven Git workflows in a native terminal interface"
  homepage "https://github.com/{repo}"
  version "{NPM_VERSION}"
  depends_on :macos
{sel}  depends_on "python@3.13"
  depends_on "git"
  depends_on "gh"
  depends_on "gitleaks"
  def install
    odie "Requires macOS {minimum} or later" if MacOS.version < "{minimum}"
    libexec.install Dir["*"]
    (bin/"gitsit").write <<~SH
      #!/bin/sh
      exec "#{{Formula["python@3.13"].opt_bin}}/python3.13" "#{{libexec}}/launch.py" "$@"
    SH
    chmod 0755, bin/"gitsit"
  end
  test do
    assert_match "GitSit Studio {VERSION}", shell_output("#{{bin}}/gitsit --version")
    assert_match "reachable", shell_output("#{{bin}}/gitsit --graph-check")
  end
end
'''

def verify_wheel(wheel,pkg):
    # Non-pure wheels can place a Python package at the archive root or in
    # the wheel .data/purelib or .data/platlib installation scheme.
    required=('gitsit-studio','core.py','bridge.py','accounts.py','native_worker.py','launch.py','__init__.py','LICENSE','THIRD_PARTY_NOTICES.txt','go.mod','go.sum')
    with zipfile.ZipFile(wheel) as z:
        names=z.namelist()
        prefixes=['gitsit_studio/']
        prefixes += [n.removesuffix('gitsit_studio/gitsit-studio')+'gitsit_studio/' for n in names if n.endswith('/gitsit_studio/gitsit-studio') and len(n.split('/'))==4 and n.split('/')[0].endswith('.data') and n.split('/')[1] in ('purelib','platlib')]
        found=[p for p in prefixes if p+'gitsit-studio' in names]
        if len(found)!=1:raise RuntimeError('Wheel must contain exactly one native Studio executable in a valid installation scheme; found '+str(found))
        prefix=found[0]
        for n in required:
            member=prefix+n
            if names.count(member)!=1:raise RuntimeError('Wheel member missing or duplicated: '+member)
            info=z.getinfo(member)
            if n=='gitsit-studio' and not ((info.external_attr>>16)&0o111):raise RuntimeError('Wheel binary not executable')
            if hashlib.sha256(z.read(info)).hexdigest()!=sha(pkg/n):raise RuntimeError('Wheel file differs from build source: '+member)
        print('Wheel contents verified:',prefix,flush=True)

def build(root,license_text,repo):
    osname,arch=host(); key=osname+'-'+arch
    for exe in ('go','git','gitleaks','npm','node'):
        if not shutil.which(exe):raise RuntimeError(exe+' missing. Install build dependencies first.')
    checks(root)
    final=root/'dist'/key
    if final.exists():raise RuntimeError('Output already exists: '+str(final))
    with tempfile.TemporaryDirectory(prefix='gitsit-build-') as t:
        tmp=Path(t);work=tmp/'source';shutil.copytree(root/'source',work,ignore=shutil.ignore_patterns('__pycache__','*.pyc'))
        meta=work/'pyproject.toml';write(meta,meta.read_text().replace('github.com/habibieebhy/gitappho','github.com/'+repo));pkg=work/'gitsit_studio'; go=work/'go'; (pkg/'test_native.py').unlink();write(pkg/'LICENSE',license_text)
        env=dict(clean_env(),GOWORK='off',GOENV='off',GOFLAGS='',GOPROXY='https://proxy.golang.org',GOSUMDB='sum.golang.org',GOPRIVATE='',GONOPROXY='',GONOSUMDB='',CGO_ENABLED='0',GOOS=osname,GOARCH='amd64' if arch=='x64' else 'arm64')
        env.pop('GOTOOLCHAIN',None)
        run(['go','mod','tidy'],cwd=go,env=env);run(['go','mod','verify'],cwd=go,env=env);run(['go','mod','vendor'],cwd=go,env=env)
        run(['go','test','-mod=vendor','.'],cwd=go,env=env);run(['go','build','-mod=vendor','-trimpath','-o',pkg/'gitsit-studio','.'],cwd=go,env=env)
        for n in ('go.mod','go.sum'):shutil.copy2(go/n,pkg/n)
        notices=[str(p.relative_to(go/'vendor'))+'\n'+p.read_text(errors='replace') for p in sorted((go/'vendor').rglob('*')) if p.is_file() and p.name.lower().startswith(('license','licence','copying','notice','copyright'))]
        if not notices:raise RuntimeError('Third-party notices missing')
        write(pkg/'THIRD_PARTY_NOTICES.txt','\n\n'.join(notices));run(['gitleaks','dir','--redact','--no-banner',pkg],env=clean_env(),timeout=120)
        stage=tmp/'artifacts';stage.mkdir(); runtime=stage/'runtime';shutil.copytree(pkg,runtime)
        archive=stage/f'gitsit-{TAG}-{key}.tar.gz'
        with tarfile.open(archive,'w:gz') as tar:
            for p in sorted(runtime.iterdir()):
                if p.is_file():tar.add(p,arcname='gitsit-'+TAG+'/'+p.name,recursive=False)
        minimum=None
        if osname=='darwin':
            parts=platform.mac_ver()[0].split('.');major,minor=map(int,parts[:2]); minimum=f'{major}.{minor}'; wheel_tag=f'macosx_{major}_{minor}_{"arm64" if arch=="arm64" else "x86_64"}' if major<11 else f'macosx_{major}_0_{"arm64" if arch=="arm64" else "x86_64"}'
        else:wheel_tag='linux_'+('aarch64' if arch=='arm64' else 'x86_64')
        # Linux wheel is local-only until a manylinux/musllinux build and audit.
        venv=tmp/'venv';run([sys.executable,'-m','venv',venv]);py=venv/'bin/python'
        wenv=dict(clean_env(),GITSIT_WHEEL_PLATFORM=wheel_tag)
        run([py,'-m','pip','wheel','--no-deps','--wheel-dir',stage,work],env=wenv)
        wheels=list(stage.glob('*.whl'))
        if len(wheels)!=1 or not wheels[0].name.endswith(wheel_tag+'.whl'):raise RuntimeError('Unexpected wheel')
        verify_wheel(wheels[0],pkg)
        run([py,'-m','pip','install','--no-deps',wheels[0]])
        run([py,'-c',"import importlib.util, pathlib, os, hashlib, sys; p=pathlib.Path(importlib.util.find_spec('gitsit_studio').origin).parent/'gitsit-studio'; assert p.is_file() and os.access(p,os.X_OK), 'Installed Studio executable missing or not executable'; assert hashlib.sha256(p.read_bytes()).hexdigest()==sys.argv[1], 'Installed executable hash mismatch'; print('Installed native Studio executable verified:',p)",sha(pkg/'gitsit-studio')],cwd=tmp,env=clean_env())
